class Solution {
public:
    int combinationSum4(vector<int>& nums, int target) {
        vector<long long> dp(target + 1, 0);
        dp[0] = 1;                         // empty sequence forms sum 0
        for (int i = 1; i <= target; ++i) {
            long long ways = 0;
            for (int x : nums) {
                if (i >= x) ways += dp[i - x];
            }
            dp[i] = ways;
        }
        return static_cast<int>(dp[target]);   // guaranteed to fit in 32‑bit
    }
};
